FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT sku, name, pack, price_inr, cost_inr, flow
FROM store.products
ORDER BY sku;

SELECT COUNT(*) as shipment_count
FROM warehouse.shipments
WHERE arrived_ts >= '2026-06-01' AND arrived_ts < '2026-07-01';

SELECT sku, name, pack, case_units, case_kg, price_inr, cost_inr
FROM store.products
WHERE name ILIKE '%atta%' OR sku ILIKE '%atta%';

